dslRule:
/*!
@id: jface.text.util.computeLineHeight
@description: Replace StyledText.getLineHeight(offset) with JFaceTextUtil.computeLineHeight(StyledText, StyledText.getLineAtOffset(offset)) for better word wrap handling.
@severity: INFO
*/
$styledText.getLineHeight($offset) :: instanceof($styledText, "org.eclipse.swt.custom.StyledText")
=>
org.eclipse.jface.text.JFaceTextUtil.computeLineHeight($styledText, $styledText.getLineAtOffset($offset))
;;

beforeExample:
package org.eclipse.jface.text;

import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.graphics.Point;
import org.eclipse.swt.graphics.Rectangle;

// Dummy ITextViewer and StyledText for compilation
interface ITextViewer { StyledText getTextWidget(); }
class DummyStyledText extends StyledText { 
    public DummyStyledText(org.eclipse.swt.widgets.Composite parent, int style) { super(parent, style); }
    @Override public int getLineHeight(int offset) { return 10; }
    @Override public Point getLocationAtOffset(int offset) { return new Point(0,0); }
    @Override public Rectangle getTextBounds(int start, int end) { return new Rectangle(0,0,1,1); }
    @Override public int getLineAtOffset(int offset) { return 0; }
}
class DummyTextViewer implements ITextViewer { public StyledText getTextWidget() { return new DummyStyledText(null, 0); } }

public class JFaceTextUtil {
    public static int getAverageCharWidth(StyledText styledText) { return 1; }
    // The new computeLineHeight API is assumed to exist for the AFTER example and rule application.
    public static int computeLineHeight(StyledText styledText, int widgetLine) { return 10; }

    public static Rectangle getTextBounds(ITextViewer textViewer, int start, int end) {
        StyledText styledText = textViewer.getTextWidget();
        Rectangle bounds;
        if (start < end)
            bounds= styledText.getTextBounds(start, end - 1);
        else {
            Point loc= styledText.getLocationAtOffset(start);
            bounds= new Rectangle(loc.x, loc.y, getAverageCharWidth(textViewer.getTextWidget()), styledText.getLineHeight(start)); // Target pattern
        }
        return new Rectangle(bounds.x, bounds.y, bounds.width, bounds.height);
    }
}

